package markdown

import (
	"fmt"
	"strings"
)

// Refactoring notes:
//
// The previous implementation walked the input one byte at a time with a pile
// of interacting flags (header, he, list, listOpened, pos) and did the
// emphasis substitution on the whole document up front. It worked, but the
// control flow was hard to follow.
//
// This version processes the input line by line, because every construct we
// support is line-oriented:
//
//   - a line starting with 1-6 '#' characters followed by a space is a
//     header of that level (7 or more '#' is not a valid level and stays
//     literal paragraph text);
//   - a line starting with "* " is a list item; consecutive items share one
//     <ul>, and the first non-list line (or end of input) closes it;
//   - any other line is a paragraph.
//
// Emphasis is applied per line: the first "__pair__" becomes <strong> and the
// first "_pair_" becomes <em>.
func Render(source string) string {
	var b strings.Builder
	inList := false

	for _, line := range strings.Split(source, "\n") {
		if line == "" {
			continue // blank lines produce no output
		}

		if isListItem(line) {
			if inList {
				b.WriteString("</li><li>")
			} else {
				b.WriteString("<ul><li>")
				inList = true
			}
			b.WriteString(applyEmphasis(strings.TrimPrefix(line, "* ")))
			continue
		}

		// A non-list line ends the current list, if any.
		if inList {
			b.WriteString("</li></ul>")
			inList = false
		}

		if level := headerLevel(line); level > 0 {
			b.WriteString(renderHeader(line, level))
			continue
		}

		b.WriteString("<p>" + applyEmphasis(line) + "</p>")
	}

	if inList {
		b.WriteString("</li></ul>")
	}

	return b.String()
}

// isListItem reports whether line is a list item ("* " prefix).
func isListItem(line string) bool {
	return strings.HasPrefix(line, "* ")
}

// headerLevel returns the header level (1-6) if line is a header, else 0.
// A header starts with 1-6 '#' characters followed by a space or the end of
// the line. 7 or more '#' characters are not a valid level.
func headerLevel(line string) int {
	level := prefixRunes(line, '#')
	if level < 1 || level > 6 {
		return 0
	}
	if len(line) > level && line[level] != ' ' {
		return 0
	}
	return level
}

// renderHeader renders a header line as <hN>text</hN>, dropping the '#'
// markers and the space that follows them.
func renderHeader(line string, level int) string {
	text := strings.TrimPrefix(line, strings.Repeat("#", level))
	text = strings.TrimPrefix(text, " ")
	return fmt.Sprintf("<h%d>%s</h%d>", level, applyEmphasis(text), level)
}

// applyEmphasis converts the first "__pair__" in s to <strong> and the first
// "_pair_" to <em>. Only the first pair of each marker is converted, as in
// the original implementation. "__" is handled before "_" so that bold
// markers are not mistaken for italic ones.
func applyEmphasis(s string) string {
	s = replaceFirstPair(s, "__", "<strong>", "</strong>")
	return replaceFirstPair(s, "_", "<em>", "</em>")
}

// replaceFirstPair wraps the first pair of delim in s in the open and close
// tags. s is returned unchanged if it does not contain a complete pair.
func replaceFirstPair(s, delim, open, close string) string {
	start := strings.Index(s, delim)
	if start < 0 {
		return s
	}
	after := s[start+len(delim):]
	end := strings.Index(after, delim)
	if end < 0 {
		return s
	}
	return s[:start] + open + after[:end] + close + after[end+len(delim):]
}

// prefixRunes counts how many times r repeats at the start of s.
func prefixRunes(s string, r rune) int {
	n := 0
	for _, c := range s {
		if c != r {
			break
		}
		n++
	}
	return n
}

